---@class IdolLive3D_TalkNode
local IdolLive3D_TalkNode = Class('IdolLive3D_TalkNode')

function IdolLive3D_TalkNode:__init()
    self.CanvasGroup = nil
    self.TxtNameTrans = nil
    self.TextDesc = nil
    self.EventPlayVideoSubtitle = nil
    self.isActive = false
    self.subtitleSegments = nil  -- 字幕数组
    self.subtitleSegmentsNum = 0 -- 字幕数组 元素个数
    self.currentSegmentIdx = 1     -- 字幕元素 idx; 1-based
    self.startTime = 0
end

function IdolLive3D_TalkNode:__delete()
    --printError("IdolLive3D_TalkNode:__delete")
    --self.CanvasGroup = nil
    self.TxtNameTrans = nil
    self.TxtDescTrans = nil
    self.EventPlayVideoSubtitle = nil
    self.subtitleSegments = nil  -- 字幕数组
    self.subtitleSegmentsNum = 0 -- 字幕数组 元素个数
    self.currentSegmentIdx = 1     -- 字幕元素 idx; 1-based
    self.startTime = 0
end

function IdolLive3D_TalkNode:Awake()
    self.TxtNameTrans = self.controller.transform:Find("TxtName")
    self.textTF = self.controller.transform:Find("TxtDesc")
    --self.CanvasGroup = CfUtils.GetOrAddComponent(self.textTF, typeof(CanvasGroup))
    self.TextDesc = KTool.GetComponent(self.textTF.gameObject, typeof(Text))
    self.EventPlayVideoSubtitle = Events.AddListener(IdolLive3D_States.EventPlayVideoSubtitle, Bind(self, self.OnTalkEventName))
end

function IdolLive3D_TalkNode:OnTalkEventName(groupId, waitTime)
    CfUtils.SetCanvasGroupAlpha( self.controller.gameObject, 1 )
    self:StartPlay(groupId, waitTime)
end

function IdolLive3D_TalkNode:Start()
    local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    if behaviourAction then
        behaviourAction.UpdateAction = function()
            self:Update()
        end
    end
end

function IdolLive3D_TalkNode:Update()
    if self.isActive == false then
        return
    end
    self:Do(Time.time - self.startTime)
end

function IdolLive3D_TalkNode:StartPlay(groupId, waitTime)
    ---取数据
    groupId = IdolLive3D_Utils.TrimTrailingSpaces( tostring(groupId) ) 
    self:SetSubtitleSegments(groupId)
    self.startTime = Time.time + checkNumber(waitTime)
    self.isActive = true
    CfUtils.SetCanvasGroupAlpha( self.controller.gameObject, 1 )
end

function IdolLive3D_TalkNode:SetSubtitleSegments(groupId)

    self.currentGroupId = groupId

    -- 区分字幕表:
    local curVoice = string.lower( tostring(SettingVoiceMgr:GetCurrentVoiceTag()) ) -- 返回 "cn" or 'jp'
    local SettingId = SettingId_jp
    if curVoice == "cn" then 
        print("选择 cn 字幕")
        SettingId = AutoIds.IdSetting6144
    elseif curVoice == "jp" then
        print("选择 jp 字幕")
        SettingId = SettingId_jp
    else 
        printError("语音参数异常: " .. tostring(curVoice))
    end 

    ---
    print( "koko 解析得字幕段 id = " .. tostring(groupId) .. ";" )
    local ids = CfUtils.GetIdGroupValue(SettingId, groupId, 'ids')
    local idList = parse_strings(ids, ',')
    local t = {}
    for i, id in pairs(idList) do
        local vo = CfUtils.GetCfVo(SettingId, "Live3DVideoSubtitleVO", id) -- Live3DVideoSubtitleVO
        table.insert( t, vo )
    end
    --self.subtitleSegments = fakeSubtitleSegments
    self.subtitleSegments = t
    -- 插入尾哨兵元素:
    local lastTimeFrom = self.subtitleSegments[table.count(self.subtitleSegments)].timeTo + 0.1
    table.insert(self.subtitleSegments, {
        timeFrom = lastTimeFrom,
        timeTo   = lastTimeFrom + segmentMinDuration,
        lecturer = 0,
        text = "",
    })

    self.subtitleSegmentsNum = table.count(self.subtitleSegments)
    self.currentSegmentIdx = 1


    -- 确保各 segments 的 timeFrom 一定是升序排序:
    self:CheckSegmentsBasicOrder_()
    if self.isError == true then 
        return
    end 

    -- 检验并修正 配表数据:
    for l=1, self.subtitleSegmentsNum-1 do -- leftIdx
        local leftSeg  = self.subtitleSegments[l]
        local rightSeg = self.subtitleSegments[l+1]
        self:AdjustSegmentParams( l, leftSeg, rightSeg )
    end

end

function IdolLive3D_TalkNode:SetMainText(str_)
    if self.TextDesc.text ~= str_ then
        print(" 设置字幕: " .. tostring(str_))
        self.TextDesc.text = str_
    end
end


function IdolLive3D_TalkNode:SetName(name_)
    CfUtils.FillText(self.TxtNameTrans, name_)
end


-- 关闭字幕
function IdolLive3D_TalkNode:EndPlay()
    self.isActive = false
    self.startTime = Time.time
end



-- 确保各 segments 的 timeFrom 一定是递增的;
function IdolLive3D_TalkNode:CheckSegmentsBasicOrder_()

    local tmpTimeFrom = self.subtitleSegments[1].timeFrom

    for i=2, self.subtitleSegmentsNum do -- leftIdx
        local newTimeFrom = self.subtitleSegments[i].timeFrom
        if newTimeFrom < tmpTimeFrom + segmentMinDuration then  
            printError( "字幕配表严重错误, timeFrom 数据错乱, newTimeFrom = " .. tostring(newTimeFrom) .. "; GroupId = " .. tostring(self.currentGroupId) )
            self.isError = true
            return
        end
        tmpTimeFrom = newTimeFrom
    end
end



-- 修正一段 segment 内的 配表数据异常:
function IdolLive3D_TalkNode:AdjustSegmentParams( idx_, segment_, nextSegment_ )
    
    -- 两个 segment 首尾交叉了:
    if nextSegment_.timeFrom < segment_.timeTo then 
        printError( "字幕配表数据异常:[强] 字幕段:" .. tostring(idx_) .. " 和后端交叉了 " )
        -- 因为在之前的 CheckSegmentsBasicOrder() 检测中, 我们已经保证每两个 timeFrom 之间一定有段间隙: segmentMinDuration, 所以 timeTo 可以放心地往前缩
        segment_.timeTo = nextSegment_.timeFrom - minTimeGap
    end

    -- 本段内部, timeFrom 和 timeTo 颠倒了
    if segment_.timeTo < segment_.timeFrom then 
        printError( "字幕配表数据异常: [强] 字幕段:" .. tostring(idx_) .. " 内部的 timeFrom 和 timeTo 颠倒了" )
        segment_.timeTo = nextSegment_.timeFrom - minTimeGap
    end 


    if (segment_.timeTo - segment_.timeFrom) < segmentMinDuration then 
        printError( "字幕配表数据异常: [弱] 字幕段:" .. tostring(idx_) .. " 内部的 timeFrom 到 timeTo 的时长太短了, 确保大于: " .. tostring(segmentMinDuration) )
        segment_.timeTo = nextSegment_.timeFrom - minTimeGap
    end 

    -- 计算 淡入淡出最大时长:
    local fadeInOutMaxDuration = (segment_.timeTo - segment_.timeFrom) * fadeInOutMaxPercent

    if segment_.fadeIn > fadeInOutMaxDuration then 
        print( "字幕配表数据异常: [弱] 字幕段:" .. tostring(idx_) .. " 内部 fadeIn 时长过长" )
        segment_.fadeIn = fadeInOutMaxDuration
    end 

    if segment_.fadeOut > fadeInOutMaxDuration then 
        print( "字幕配表数据异常: [弱] 字幕段:" .. tostring(idx_) .. " 内部 fadeOut 时长过长" )
        segment_.fadeOut = fadeInOutMaxDuration
    end 
end


function IdolLive3D_TalkNode:Do( currentTime_ )
    if self.currentSegmentIdx < 1 or self.currentSegmentIdx > self.subtitleSegmentsNum then
        printError( "数据异常" )
        CfUtils.SetCanvasGroupAlpha( self.controller.gameObject, 0 )
        CfUtils.SetCanvasGroupAlpha( self.textTF.gameObject, 0 )
        --self.CanvasGroup.alpha = 0.0
        self:SetMainText(" ")
        self:SetName(" ")
        return
    end

    -- 第一段字幕之前:
    if currentTime_ < self.subtitleSegments[1].timeFrom then
        --print("[未开始]")
        CfUtils.SetCanvasGroupAlpha( self.textTF.gameObject, 0 )
        --self.CanvasGroup.alpha = 0.0
        self:SetMainText("")
        self:SetName(" ")
        return
    end

    -- 最后一段字幕之后:
    if currentTime_ >= self.subtitleSegments[self.subtitleSegmentsNum].timeTo then
        ---播放结束
        --print("[已结束]")
        CfUtils.SetCanvasGroupAlpha( self.controller.gameObject, 0 )
        CfUtils.SetCanvasGroupAlpha( self.textTF.gameObject, 0 )
        --self.CanvasGroup.alpha = 0.0
        return
    end

    --- 找到正确的 当前 字幕段:
    local newSegmentIdx = nil
    for l=self.currentSegmentIdx, self.subtitleSegmentsNum-1 do -- leftIdx
        local leftSeg  = self.subtitleSegments[l]
        local rightSeg = self.subtitleSegments[l+1]

        if currentTime_ >= leftSeg.timeFrom and currentTime_ < rightSeg.timeFrom then
            newSegmentIdx = l
            break
        end
    end
    if isNull( newSegmentIdx ) then
        -- 说明进入 尾哨兵元素区间了, 直接返回
        return
    end
    self.currentSegmentIdx = newSegmentIdx
    local nowSegment =self.subtitleSegments[self.currentSegmentIdx]

    -- 开始正式处理 segment:
    local fadeInBegin  = nowSegment.timeFrom
    local fadeInEnd    = nowSegment.timeFrom + nowSegment.fadeIn
    local fadeOutBegin = nowSegment.timeTo - nowSegment.fadeOut
    local fadeOutEnd   = nowSegment.timeTo

    -- 计算并设置 淡入淡出 alpha 值:
    local alpha = 0
    if currentTime_ < fadeInEnd then
        -- 淡入:
        alpha = KTool.Remap( fadeInBegin, fadeInEnd, 0.0, 1.0, currentTime_ )

    elseif currentTime_ < fadeOutBegin then
        -- 全显:
        alpha = 1.0

    elseif currentTime_ <= fadeOutEnd then
        -- 淡出:
        alpha = KTool.Remap( fadeOutBegin, fadeOutEnd, 1.0, 0.0, currentTime_ )

    else
        -- 此时位于 不显示阶段
    end
    CfUtils.SetCanvasGroupAlpha( self.textTF.gameObject, alpha )
    --self.CanvasGroup.alpha = alpha
    --print( "a = " .. tostring(alpha) )

    --- 配置文本:
    if currentTime_ <= nowSegment.timeTo then

        local name = self.skinName
        if nowSegment.lecturer == 1 then 
            name = self.playerName
        elseif nowSegment.lecturer == 2 then 
            name = " "
        end 
        self:SetMainText( nowSegment.subtitle )
        self:SetName( name )

    else
        self:SetMainText(" ")
        self:SetName(" ")
    end
end


