---设置角色名称
---@param name string
function IdolLive3D_TalkNode:Init(cardSkinId_)

    local live3DCardVoRow = IdolLive3D_Utils.GetLive3DCardVoRow(cardSkinId_)
    local playerComp = ChapterUtils.GetPlayerComp()
    -- 
    self.skinName = live3DCardVoRow.name
    self.playerName = playerComp.playerDojo.playerName
    --
    CfUtils.SetActive(self.controller.gameObject, true)
    CfUtils.SetCanvasGroupAlpha( self.controller.gameObject, 0 )
end


function IdolLive3D_TalkNode:OnDestroy()

    if self.EventPlayVideoSubtitle then
        Events.RemoveListener(IdolLive3D_States.EventPlayVideoSubtitle, self.EventPlayVideoSubtitle)
        self.EventPlayVideoSubtitle = nil
    end

    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return IdolLive3D_TalkNode